    try {
      const ws = new WebSocket('wss://echo.websocket.events');
      setTimeout(() => ws.close(), 100);
    } catch(e) {}
  });
  await page.waitForTimeout(500);
  if (typeof closed === 'boolean') console.log('LEVEL_PASSED');
  await browser.close();
})();

