import React from 'react';
import { HeroCard } from '../../components/HeroCard.jsx';

describe('HeroCard', () => {
  it('renders hero name, class, level, and guild', () => {
      cy.mount(
        <HeroCard name="Aria Stormwind" heroClass="Archer" level={42} guild="Silver Hawks" />
      );
